package com.indiesoundquest.tournament.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="tournament_entry") public class TournamentEntry {
 @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="tournament_id",nullable=false) private Tournament tournament; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="recording_id",nullable=false) private Recording recording; @Column(name="title_snapshot",nullable=false) private String titleSnapshot; @Column(name="artist_name_snapshot",nullable=false) private String artistNameSnapshot; @Column(name="album_title_snapshot") private String albumTitleSnapshot; @Column(name="version_label_snapshot") private String versionLabelSnapshot;
 protected TournamentEntry(){} public static TournamentEntry from(UUID id,Tournament tournament,Recording recording,String artistName){var e=new TournamentEntry();e.id=id;e.tournament=tournament;e.recording=recording;e.titleSnapshot=recording.getTitle();e.artistNameSnapshot=artistName;e.albumTitleSnapshot=recording.getAlbumTitle();e.versionLabelSnapshot=recording.getVersionLabel();return e;} public UUID getId(){return id;} public String getTitleSnapshot(){return titleSnapshot;} public String getArtistNameSnapshot(){return artistNameSnapshot;} public String getAlbumTitleSnapshot(){return albumTitleSnapshot;} public String getVersionLabelSnapshot(){return versionLabelSnapshot;} public Recording getRecording(){return recording;}
}
